INSERT INTO `events` (`event_id`, `event_name`, `event_description`, `cover_image`, `start_date`, `end_date`, `applications_count`, `owner_id`, `disapproval_reason`, `is_disapproved`, `is_approved`, `venue`, `event_contact_email`) VALUES
(7, 'Python Chat Bot Hackathon', 'h1: Python Chat Bot Hackathon :h1\r\n\r\nJoin us for an exciting Python Chat Bot Hackathon where participants can showcase their creativity and coding skills! Whether you\'re a seasoned developer or just starting out with Python, this event is designed for anyone interested in building chat bots.\r\n\r\nh2: Event Details :h2\r\n\r\nDate: 29-07-2024\r\nTime: 9 AM\r\nLocation: Nellore\r\nHighlights:\r\n\r\nChallenge: Participants will compete to create innovative chat bots using Python.\r\nLearning: Engage with like-minded developers and learn new skills.\r\nPrizes: Exciting prizes for top performers and innovative creations.\r\nNetworking: Opportunity to network with industry professionals and fellow developers.\r\nWho Can Participate:\r\n\r\nDevelopers of all skill levels who have an interest in Python programming and chat bot development.\r\nTeams are welcome! (Specify team size and composition rules if any)\r\nHow to Register:\r\n\r\nRegistration details will be announced soon. Stay tuned for updates!\r\nWhy Participate:\r\n\r\nGain hands-on experience in Python development.\r\nShowcase your skills to industry experts.\r\nWin prizes and recognition for your creativity and innovation.\r\nDon\'t miss out on this opportunity to dive into Python programming and chat bot development. Mark your calendars and get ready to hack away!', , '2024-07-02', '2024-07-10', 7, 14, NULL, 0, 0, 'Nellore', 'prasunet@gmail.com');
INSERT INTO `events` (`event_id`, `event_name`, `event_description`, `cover_image`, `start_date`, `end_date`, `applications_count`, `owner_id`, `disapproval_reason`, `is_disapproved`, `is_approved`, `venue`, `event_contact_email`) VALUES
(8, 'Monsoon Hackathon: Igniting Innovation in Rainy Season', 'Join us for the Monsoon Hackathon, where creativity meets technology amidst the soothing rains. This event is a gathering of bright minds and tech enthusiasts eager to innovate and solve real-world challenges. Whether you\'re a seasoned developer, a creative designer, or an entrepreneurial thinker, this hackathon offers you a platform to collaborate, create, and showcase your skills.\r\n\r\nh2: Event Highlights :h2\r\n\r\nDates: 29-07-2024\r\nLocation: India\r\nTheme: Embrace the Monsoon Spirit\r\nActivities: Coding challenges, design sprints, team collaborations, and more\r\nPrizes: Exciting rewards for top innovations\r\nNetworking: Connect with industry experts and peers\r\nWhy Join?\r\n\r\nInnovate: Develop solutions that make an impact.\r\nLearn: Gain insights from mentors and peers.\r\nNetwork: Build connections with like-minded individuals.\r\nFun: Engage in a lively and inspiring atmosphere.\r\nDon\'t miss this opportunity to dive into the world of innovation and make a splash at the Monsoon Hackathon. Register now and bring your ideas to life!', , '2024-07-02', '2024-07-06', 10, 14, NULL, 0, 0, 'India', 'prasunet@gmail.com');
INSERT INTO `events` (`event_id`, `event_name`, `event_description`, `cover_image`, `start_date`, `end_date`, `applications_count`, `owner_id`, `disapproval_reason`, `is_disapproved`, `is_approved`, `venue`, `event_contact_email`) VALUES
(11, 'RideBikes Campaign: Join Us in Making a Difference!', 'Are you passionate about cycling and environmental sustainability? The RideBikes Campaign invites you to be part of a movement that promotes eco-friendly transportation and community engagement.\r\n\r\nCampaign Goals:\r\n\r\nPromote Cycling: Encourage more people to adopt cycling as a sustainable mode of transportation.\r\nEnvironmental Impact: Reduce carbon footprint and promote cleaner air through cycling.\r\nCommunity Engagement: Engage local communities in cycling events and awareness programs.\r\nVolunteer Opportunities:\r\n\r\nEvent Organizers: Help plan and coordinate cycling events and workshops.\r\nPromoters: Spread awareness about the benefits of cycling and the campaign\'s goals.\r\nSupport Team: Assist in logistics, setup, and coordination during events.\r\nContact Information:\r\nFor more details and to get involved, please contact us at venuorg@gmail.com or visit  venuorg.com', , '2024-08-07', '0000-00-00', 0, 25, NULL, 0, 0, 'Nellore', 'ramu@gmail.com');

